import React from 'react';
import './Ahorro.css'; // Asegúrate de importar el CSS si lo tienes

const Ahorro = ({ salary, paysServices, monthlyExpenses }) => {

    const [activeTab, setActiveTab] = useState('inicio');
    const [initialForm, setInitialForm] = useState({});
    const [goalForm, setGoalForm] = useState({});
    const [saveForm, setSaveForm] = useState({});
    const [retireForm, setRetireForm] = useState({});

    useEffect(() => {
        if (user._id) {
            fetchFormData('initial', setInitialForm);
            fetchFormData('goals', setGoalForm);
            fetchFormData('save', setSaveForm);
            fetchFormData('retires', setRetireForm);
        }
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [user._id]);

    const fetchFormData = async (formType, setFormState) => {
        try {
            const response = await fetch(`http://localhost:5000/api/forms/${formType}/get${capitalize(formType)}/${user._id}`);
            const result = await response.json();
            setFormState(result);
        } catch (error) {
            console.error(`Error fetching ${formType} form data:`, error);
        }
    };

    const capitalize = (string) => string.charAt(0).toUpperCase() + string.slice(1);

    return (
        <>
            <div className="ahorro-container">
                <h1 className="ahorro-title">Ahorro</h1>
                <div className="tab-section">
                    <h3>Formulario Inicial</h3>
                    <p>Salario: {salary}</p>
                    <p>Paga Servicios: {paysServices ? 'Sí' : 'No'}</p>
                    <p>Gastos Mensuales: {monthlyExpenses}</p>
                </div>
                <div className="ahorro-content">
                    {/* Aquí puedes añadir contenido adicional específico del componente Ahorro */}
                </div>
            </div>
        </>
    );
};

export default Ahorro;
